import uuid
import datetime
from feast import FeatureStore
from pydantic import BaseModel, ValidationError

class FeatureDefinition(BaseModel):
    name: str
    owner: str
    version: str
    source_table: str
    description: str
    tags: list[str]

class FeatureRegistry:
    def __init__(self, feast_repo_path: str):
        self.store = FeatureStore(repo_path=feast_repo_path)

    def register_feature(self, feature_def: FeatureDefinition):
        try:
            feature_id = str(uuid.uuid4())
            metadata = {
                'lineage': f'Source: {feature_def.source_table}',
                'created_at': datetime.datetime.utcnow().isoformat()
            }
            # Simulated registration in Feast registry (Feast API call here)
            print(f'Registered feature {feature_def.name} v{feature_def.version} by {feature_def.owner}')
            return {
                'status': 'success',
                'feature_id': feature_id,
                'metadata': metadata
            }
        except ValidationError as e:
            return {'status': 'error', 'message': str(e)}

