import redis
import json

class FeatureServingClient:
    def __init__(self, redis_url: str):
        self.redis = redis.Redis.from_url(redis_url)

    def get_features(self, entity_keys: list[str], feature_list: list[str]):
        results = {}
        for key in entity_keys:
            raw = self.redis.get(key)
            if not raw:
                continue
            data = json.loads(raw)
            results[key] = {f: data.get(f) for f in feature_list}
        return results

from fastapi import APIRouter
from pydantic import BaseModel
from sdk.registry import FeatureRegistry, FeatureDefinition

router = APIRouter(prefix='/api/features', tags=['features'])
registry = FeatureRegistry(feast_repo_path='./feast_repo')

class FeatureRequest(BaseModel):
    name: str
    owner: str
    version: str
    source_table: str
    description: str
    tags: list[str]

@router.post('/register')
def register_feature(req: FeatureRequest):
    feature_def = FeatureDefinition(**req.dict())
    response = registry.register_feature(feature_def)
    return response

