from fastapi import APIRouter
from pydantic import BaseModel
from sdk.serving import FeatureServingClient

router = APIRouter(prefix='/api/serving', tags=['serving'])
serving_client = FeatureServingClient(redis_url='redis://localhost:6379')

class ServingRequest(BaseModel):
    entity_keys: list[str]
    feature_list: list[str]

@router.get('/realtime')
def serve_features(req: ServingRequest):
    features = serving_client.get_features(req.entity_keys, req.feature_list)
    return {'features': features}
